 * Author: @ijila-itunu (https://tailwindflex.com/@ijila-itunu)
 * Source: https://tailwindflex.com/@ijila-itunu/multi-step-form-component
 * Attribution: Créé par @ijila-itunu sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function MultiStepFormComponent() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Multi-Step Form Wizard t</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Syne:wght@400;600;700;800&family=JetBrains+Mono:ital,wght@0,300;0,400;0,500;1,400&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg:            #060608;
      --surface:       #0f0f16;
      --surface-2:     #141420;
      --border:        #1e1e2f;
      --border-hover:  rgba(74,222,128,.25);
      --accent:        #4ade80;
      --accent-dim:    rgba(74,222,128,.12);
      --accent-glow:   rgba(74,222,128,.28);
      --cyan:          #22d3ee;
      --cyan-dim:      rgba(34,211,238,.12);
      --text:          #e8e8f0;
      --text-dim:      #6b6b8a;
      --text-muted:    #38384e;
      --error:         #f87171;
      --error-dim:     rgba(248,113,113,.12);
      --radius:        14px;
      --radius-sm:     8px;
      --font-head:     'Syne', sans-serif;
      --font-mono:     'JetBrains Mono', monospace;
      --transition:    cubic-bezier(.4,0,.2,1);
    }

    body {
      background: var(--bg);
      color: var(--text);
      font-family: var(--font-mono);
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 2rem 1rem;
      position: relative;
      overflow-x: hidden;
    }

    /* Grid background */
    body::before {
      content: '';
      position: fixed; inset: 0;
      background-image:
        linear-gradient(rgba(74,222,128,.025) 1px, transparent 1px),
        linear-gradient(90deg, rgba(74,222,128,.025) 1px, transparent 1px);
      background-size: 44px 44px;
      pointer-events: none;
      z-index: 0;
    }

    /* Top glow orb */
    body::after {
      content: '';
      position: fixed;
      width: 700px; height: 500px;
      border-radius: 50%;
      background: radial-gradient(ellipse, rgba(74,222,128,.055) 0%, transparent 70%);
      top: -160px; left: 50%;
      transform: translateX(-50%);
      pointer-events: none;
      z-index: 0;
    }

    .wizard-wrapper {
      width: 100%; max-width: 640px;
      position: relative; z-index: 1;
    }

    /* ── Header Badge ───────────────────────────────── */
    .wizard-badge {
      display: inline-flex; align-items: center; gap: 8px;
      background: var(--accent-dim);
      border: 1px solid rgba(74,222,128,.2);
      color: var(--accent);
      font-size: 10px; font-weight: 500;
      letter-spacing: .15em; text-transform: uppercase;
      padding: 5px 14px; border-radius: 100px;
      margin-bottom: 1.25rem;
    }
    .wizard-badge::before {
      content: '';
      width: 6px; height: 6px; border-radius: 50%;
      background: var(--accent);
      animation: blink 2s ease-in-out infinite;
    }
    @keyframes blink { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.4;transform:scale(.75)} }

    /* ── Restore Banner ─────────────────────────────── */
    #restore-banner {
      display: none;
      background: var(--accent-dim);
      border: 1px solid rgba(74,222,128,.2);
      border-radius: var(--radius-sm);
      padding: 12px 16px;
      margin-bottom: 1rem;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      font-size: 11px;
      color: var(--accent);
      animation: slideDown .3s var(--transition);
    }
    @keyframes slideDown { from{opacity:0;transform:translateY(-8px)} to{opacity:1;transform:translateY(0)} }
    .restore-actions { display: flex; gap: 8px; flex-shrink: 0; }
    .rb-btn {
      padding: 4px 12px; border-radius: 6px;
      font-size: 10px; font-family: var(--font-mono);
      cursor: pointer; border: 1px solid; transition: all .2s;
      letter-spacing: .05em;
    }
    .rb-btn.yes { border-color: var(--accent); color: var(--accent); background: transparent; }
    .rb-btn.yes:hover { background: var(--accent-dim); }
    .rb-btn.no  { border-color: var(--border); color: var(--text-dim); background: transparent; }
    .rb-btn.no:hover { border-color: var(--text-dim); }

    /* ── Card ───────────────────────────────────────── */
    .wizard-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 20px;
      overflow: hidden;
      box-shadow:
        0 0 0 1px rgba(74,222,128,.04),
        0 40px 90px rgba(0,0,0,.65);
    }

    /* ── Progress Header ────────────────────────────── */
    .progress-header {
      padding: 1.75rem 2.5rem 1.5rem;
      border-bottom: 1px solid var(--border);
      background: var(--surface-2);
    }
    .step-counter {
      font-size: 10px; color: var(--text-dim);
      letter-spacing: .1em; text-transform: uppercase;
      margin-bottom: .85rem;
    }
    .step-counter span { color: var(--accent); }

    .stepper { display: flex; align-items: flex-start; }
    .stepper-item { display: flex; align-items: flex-start; flex: 1; }
    .stepper-item:last-child { flex: 0; }

    .step-dot-col {
      display: flex; flex-direction: column;
      align-items: center; gap: 5px;
    }
    .step-dot {
      width: 30px; height: 30px; border-radius: 50%;
      border: 1.5px solid var(--border);
      display: flex; align-items: center; justify-content: center;
      font-size: 10px; font-weight: 500; color: var(--text-muted);
      background: var(--surface); flex-shrink: 0;
      transition: all .35s var(--transition);
    }
    .step-dot.active {
      border-color: var(--accent); color: var(--accent);
      background: var(--accent-dim);
      box-shadow: 0 0 14px var(--accent-glow);
    }
    .step-dot.done {
      border-color: var(--accent); background: var(--accent);
      color: #000; font-size: 12px;
    }
    .dot-check { display: none; }
    .step-dot.done .dot-num { display: none; }
    .step-dot.done .dot-check { display: block; font-weight: 700; }

    .step-lbl {
      font-size: 9px; letter-spacing: .08em; text-transform: uppercase;
      color: var(--text-muted); white-space: nowrap;
      transition: color .3s;
    }
    .step-lbl.active { color: var(--accent); }
    .step-lbl.done   { color: var(--text-dim); }

    .step-track {
      flex: 1; height: 1.5px;
      background: var(--border);
      margin: 14px 8px 0;
      border-radius: 2px; overflow: hidden; position: relative;
    }
    .step-fill {
      position: absolute; inset-block: 0; left: 0;
      width: 0%; background: var(--accent);
      border-radius: 2px;
      box-shadow: 0 0 6px var(--accent-glow);
      transition: width .55s var(--transition);
    }

    /* ── Form Body ──────────────────────────────────── */
    .form-body {
      min-height: 390px;
      position: relative; overflow: hidden;
    }

    .step-panel {
      position: absolute; inset: 0;
      padding: 2.25rem 2.5rem;
      opacity: 0; pointer-events: none;
      transform: translateX(48px);
      transition: opacity .38s var(--transition), transform .38s var(--transition);
      will-change: transform, opacity;
    }
    .step-panel.active {
      position: relative; inset: auto;
      opacity: 1; pointer-events: all;
      transform: translateX(0);
    }
    .step-panel.exit-l { opacity: 0; transform: translateX(-48px); position: absolute; inset: 0; }
    .step-panel.exit-r { opacity: 0; transform: translateX( 48px); position: absolute; inset: 0; }
    .step-panel.enter-r { transform: translateX( 48px); }
    .step-panel.enter-l { transform: translateX(-48px); }

    .step-title {
      font-family: var(--font-head);
      font-size: 1.55rem; font-weight: 800;
      color: var(--text); margin-bottom: .3rem; line-height: 1.2;
    }
    .step-sub {
      font-size: 11.5px; color: var(--text-dim);
      margin-bottom: 1.75rem; line-height: 1.65;
    }

    /* ── Fields ─────────────────────────────────────── */
    .field { margin-bottom: 1.1rem; }
    label {
      display: block;
      font-size: 9.5px; font-weight: 500;
      letter-spacing: .12em; text-transform: uppercase;
      color: var(--text-dim); margin-bottom: 7px;
    }
    label .req { color: var(--accent); margin-left: 2px; }

    input[type=text], input[type=email], input[type=url], select {
      width: 100%;
      background: var(--surface-2);
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      padding: 11px 15px;
      color: var(--text);
      font-family: var(--font-mono);
      font-size: 12.5px;
      outline: none;
      transition: border-color .22s, box-shadow .22s;
      appearance: none; -webkit-appearance: none;
    }
    input::placeholder { color: var(--text-muted); }
    input:focus, select:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 3px var(--accent-dim);
    }
    input.err, select.err {
      border-color: var(--error);
      box-shadow: 0 0 0 3px var(--error-dim);
      animation: shake .38s ease;
    }
    @keyframes shake {
      0%,100%{transform:translateX(0)}
      20%{transform:translateX(-6px)} 40%{transform:translateX(5px)}
      60%{transform:translateX(-3px)} 80%{transform:translateX(3px)}
    }
    select option { background: var(--surface-2); }

    .field-err {
      font-size: 10.5px; color: var(--error);
      margin-top: 5px; display: none;
    }
    .field-err.show { display: block; }

    /* ── Role Cards ─────────────────────────────────── */
    .role-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 9px; margin-bottom: .5rem;
    }
    .role-card {
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      padding: 13px 8px;
      text-align: center; cursor: pointer;
      transition: border-color .2s, background .2s, box-shadow .2s;
      background: var(--surface-2); user-select: none;
    }
    .role-card:hover { border-color: var(--border-hover); }
    .role-card.selected {
      border-color: var(--accent); background: var(--accent-dim);
      box-shadow: 0 0 14px var(--accent-glow);
    }
    .rc-icon { font-size: 1.4rem; margin-bottom: 5px; }
    .rc-name { font-size: 10px; color: var(--text-dim); letter-spacing: .04em; }
    .role-card.selected .rc-name { color: var(--accent); }

    /* ── Conditional Field ──────────────────────────── */
    .cond-field {
      max-height: 0; overflow: hidden; opacity: 0;
      transition: max-height .4s var(--transition), opacity .3s;
    }
    .cond-field.show { max-height: 90px; opacity: 1; }
    .cond-field .field { margin-bottom: 0; margin-top: 10px; }

    /* ── Notification Cards ─────────────────────────── */
    .notif-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 9px; margin-bottom: 1rem;
    }
    .notif-card {
      border: 1px solid var(--border); border-radius: var(--radius-sm);
      padding: 12px 8px; text-align: center; cursor: pointer;
      transition: all .2s; background: var(--surface-2); user-select: none;
    }
    .notif-card:hover { border-color: var(--border-hover); }
    .notif-card.selected { border-color: var(--accent); background: var(--accent-dim); }
    .notif-card .ni { font-size: 1.25rem; margin-bottom: 4px; }
    .notif-card .nn { font-size: 10px; color: var(--text-dim); letter-spacing: .04em; }
    .notif-card.selected .nn { color: var(--accent); }

    /* ── Toggle Row ─────────────────────────────────── */
    .toggle-row {
      display: flex; align-items: center;
      justify-content: space-between;
      padding: 13px 15px;
      background: var(--surface-2); border: 1px solid var(--border);
      border-radius: var(--radius-sm); margin-bottom: 9px;
      cursor: pointer; transition: border-color .2s; gap: 12px;
    }
    .toggle-row:hover { border-color: var(--border-hover); }
    .tr-title { font-size: 12px; font-weight: 500; color: var(--text); }
    .tr-desc  { font-size: 10px; color: var(--text-dim); margin-top: 1px; }
    .toggle {
      width: 38px; height: 21px;
      background: var(--border); border-radius: 100px;
      position: relative; transition: background .3s; flex-shrink: 0;
    }
    .toggle::after {
      content: '';
      position: absolute; width: 15px; height: 15px;
      border-radius: 50%; background: #fff;
      top: 3px; left: 3px;
      transition: transform .28s var(--transition);
    }
    .toggle.on { background: var(--accent); }
    .toggle.on::after { transform: translateX(17px); }

    /* ── Topic Chips (conditional) ──────────────────── */
    .topics-wrap {
      max-height: 0; overflow: hidden; opacity: 0;
      transition: max-height .4s var(--transition), opacity .3s;
    }
    .topics-wrap.show { max-height: 140px; opacity: 1; }
    .topics-head {
      font-size: 9.5px; letter-spacing: .1em; text-transform: uppercase;
      color: var(--text-dim); margin-bottom: 8px; padding-top: 10px;
    }
    .topics-grid { display: flex; flex-wrap: wrap; gap: 6px; }
    .topic-chip {
      padding: 5px 12px;
      border: 1px solid var(--border); border-radius: 6px;
      font-size: 10px; font-weight: 500; font-family: var(--font-mono);
      cursor: pointer; transition: all .18s;
      background: var(--surface-2); color: var(--text-dim);
      user-select: none; letter-spacing: .04em;
    }
    .topic-chip.sel {
      border-color: var(--cyan);
      background: var(--cyan-dim); color: var(--cyan);
    }

    /* ── Goals ──────────────────────────────────────── */
    .goals-grid { display: flex; flex-wrap: wrap; gap: 8px; }
    .goal-tag {
      padding: 8px 14px;
      border: 1px solid var(--border); border-radius: 100px;
      font-size: 11px; font-weight: 500; font-family: var(--font-mono);
      cursor: pointer; transition: all .18s;
      background: var(--surface-2); color: var(--text-dim);
      user-select: none; letter-spacing: .03em;
    }
    .goal-tag:hover { border-color: var(--border-hover); color: var(--text); }
    .goal-tag.sel {
      border-color: var(--accent); background: var(--accent-dim);
      color: var(--accent); box-shadow: 0 0 8px rgba(74,222,128,.2);
    }
    #goal-count { color: var(--accent); }

    /* ── Review ─────────────────────────────────────── */
    .rev-section { margin-bottom: 1.1rem; }
    .rev-section-title {
      font-size: 9px; letter-spacing: .15em; text-transform: uppercase;
      color: var(--text-muted); margin-bottom: 7px;
    }
    .rev-grid {
      background: var(--surface-2);
      border: 1px solid var(--border);
      border-radius: var(--radius-sm); overflow: hidden;
    }
    .rev-row {
      display: flex; justify-content: space-between;
      align-items: center; padding: 9px 13px;
      border-bottom: 1px solid var(--border); gap: 12px;
    }
    .rev-row:last-child { border-bottom: none; }
    .rev-key { font-size: 10px; color: var(--text-dim); letter-spacing: .04em; flex-shrink: 0; }
    .rev-val { font-size: 11px; color: var(--text); text-align: right; word-break: break-all; }
    .rev-val.ac { color: var(--accent); }
    .rev-tags { display: flex; flex-wrap: wrap; gap: 4px; justify-content: flex-end; }
    .rev-tag {
      font-size: 9px; padding: 2px 8px;
      border: 1px solid var(--accent); border-radius: 100px; color: var(--accent);
    }
    .rev-tag.cyan {
      border-color: var(--cyan); color: var(--cyan);
    }

    /* ── Footer ─────────────────────────────────────── */
    .form-footer {
      padding: 1.25rem 2.5rem;
      border-top: 1px solid var(--border);
      display: flex; align-items: center;
      justify-content: space-between;
      background: var(--surface-2);
    }
    .footer-left { display: flex; align-items: center; gap: 10px; }

    .btn {
      display: inline-flex; align-items: center; gap: 7px;
      padding: 10px 20px; border-radius: var(--radius-sm);
      font-family: var(--font-mono); font-size: 11.5px; font-weight: 500;
      letter-spacing: .05em; cursor: pointer;
      transition: all .2s; border: 1px solid transparent; outline: none;
    }
    .btn-ghost {
      background: transparent; border-color: var(--border); color: var(--text-dim);
    }
    .btn-ghost:hover { border-color: var(--text-dim); color: var(--text); }
    .btn-primary { background: var(--accent); color: #000; font-weight: 600; }
    .btn-primary:hover {
      background: #6ee7a0;
      box-shadow: 0 0 22px var(--accent-glow);
      transform: translateY(-1px);
    }
    .btn-primary:active { transform: translateY(0); }

    .save-indicator {
      display: flex; align-items: center; gap: 5px;
      font-size: 9.5px; color: var(--text-muted); letter-spacing: .05em;
      transition: color .3s; user-select: none;
    }
    .save-indicator.saved { color: var(--accent); }
    .save-dot { width: 5px; height: 5px; border-radius: 50%; background: currentColor; }

    /* ── Success Screen ─────────────────────────────── */
    #success-card { display: none; }
    .success-body {
      display: flex; flex-direction: column;
      align-items: center; justify-content: center;
      text-align: center; padding: 3.5rem 2.5rem;
      min-height: 420px;
    }
    .success-icon {
      width: 78px; height: 78px; border-radius: 50%;
      background: var(--accent-dim);
      border: 1.5px solid var(--accent);
      display: flex; align-items: center; justify-content: center;
      font-size: 2rem; margin: 0 auto 1.5rem;
      box-shadow: 0 0 40px var(--accent-glow);
      animation: pop .5s var(--transition);
    }
    @keyframes pop { from{transform:scale(.5);opacity:0} to{transform:scale(1);opacity:1} }
    .success-title {
      font-family: var(--font-head);
      font-size: 2.1rem; font-weight: 800; margin-bottom: .5rem;
      background: linear-gradient(135deg, var(--accent) 30%, var(--cyan));
      -webkit-background-clip: text; -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .success-sub {
      font-size: 11.5px; color: var(--text-dim);
      margin-bottom: 2rem; max-width: 310px; line-height: 1.7;
    }
    .success-meta {
      display: flex; gap: 16px; margin-bottom: 2rem; flex-wrap: wrap;
      justify-content: center;
    }
    .sm-chip {
      background: var(--surface-2); border: 1px solid var(--border);
      border-radius: 100px; padding: 5px 14px;
      font-size: 10px; color: var(--text-dim); letter-spacing: .05em;
    }
    .sm-chip span { color: var(--accent); }
  </style>
</head>
<body>
  <div class="wizard-wrapper">



    <!-- Restore banner -->
    <div id="restore-banner">
      <span>↩ Saved progress detected — continue where you left off?</span>
      <div class="restore-actions">
        <button class="rb-btn yes">Continue</button>
        <button class="rb-btn no" >Start fresh</button>
      </div>
    </div>

    <!-- Main card -->
    <div class="wizard-card" id="main-card">

      <!-- Stepper -->
      <div class="progress-header">
        <div class="step-counter">Step <span id="cur-num">1</span> of 5</div>
        <div class="stepper" id="stepper"></div>
      </div>

      <!-- Panels -->
      <div class="form-body" id="form-body">

        <!-- ① Personal Info -->
        <div class="step-panel active" id="panel-1">
          <div class="step-title">Who are you?</div>
          <div class="step-sub">The basics first — your data stays in your browser, never sent anywhere.</div>

          <div class="field">
            <label>Full Name <span class="req">*</span></label>
            <input type="text" id="f-name" placeholder="e.g. Ada Lovelace" autocomplete="off">
            <div class="field-err" id="e-name">Name must be at least 2 characters.</div>
          </div>
          <div class="field">
            <label>Email Address <span class="req">*</span></label>
            <input type="email" id="f-email" placeholder="ada@example.com" autocomplete="off">
            <div class="field-err" id="e-email">Please enter a valid email address.</div>
          </div>
          <div class="field">
            <label>Username <span class="req">*</span></label>
            <input type="text" id="f-username" placeholder="ada_codes" autocomplete="off">
            <div class="field-err" id="e-username">3+ chars, letters / numbers / underscores only.</div>
          </div>
        </div>

        <!-- ② Your Role -->
        <div class="step-panel" id="panel-2">
          <div class="step-title">Your Role</div>
          <div class="step-sub">Pick the role that best describes you — it unlocks a tailored field just for you.</div>

          <div class="field">
            <label>I am a… <span class="req">*</span></label>
            <div class="role-grid">
              <div class="role-card" data-role="Developer"      ><div class="rc-icon">💻</div><div class="rc-name">Developer</div></div>
              <div class="role-card" data-role="Designer"       ><div class="rc-icon">🎨</div><div class="rc-name">Designer</div></div>
              <div class="role-card" data-role="Product Manager"><div class="rc-icon">📋</div><div class="rc-name">Product Manager</div></div>
              <div class="role-card" data-role="Marketer"       ><div class="rc-icon">📣</div><div class="rc-name">Marketer</div></div>
              <div class="role-card" data-role="Founder"        ><div class="rc-icon">🚀</div><div class="rc-name">Founder</div></div>
              <div class="role-card" data-role="Other"          ><div class="rc-icon">✨</div><div class="rc-name">Other</div></div>
            </div>
            <div class="field-err" id="e-role">Please choose a role to continue.</div>
          </div>

          <!-- Conditional fields (one per role) -->
          <div class="cond-field" id="cond-Developer">
            <div class="field"><label>GitHub Profile URL</label>
              <input type="url" id="f-github" placeholder="https://github.com/yourusername">
              <div class="field-err" id="e-github">Must be a valid URL starting with https://</div>
            </div>
          </div>
          <div class="cond-field" id="cond-Designer">
